python3 -c "
import json
with open('/app/resources/treasury_bulletin_2020_03.json', 'r') as f:
    data = json.load(f)

# Print the keys at the top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) < 10 and indent < 2:
        for item in d[:3]:
            print_structure(item, indent + 2)

print_structure(data)
" 2>&1 | head -100

python3 -c "
import json
with open('/app/resources/treasury_bulletin_2020_03.json', 'r') as f:
    data = json.load(f)

# Find GDP-related content
def search_gdp(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'gdp' in k.lower() or 'growth' in k.lower():
                print(f'{path}.{k}')
            search_gdp(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search_gdp(item, f'{path}[{i}]')

search_gdp(data)
" 2>&1 | head -50

