import json
with open('/app/resources/treasury_bulletin_2020_03.json', 'r') as f:
    data = json.load(f)

doc = data.get('document', {})
elements = doc.get('elements', [])
print(f'Number of elements: {len(elements)}')

if elements:
    for i, elem in enumerate(elements[:5]):
        print(f'Element {i} keys: {elem.keys() if isinstance(elem, dict) else type(elem)}')
        if isinstance(elem, dict):
            for k, v in elem.items():
                if isinstance(v, str):
                    print(f'  {k}: {v[:100]}...')
                else:
                    print(f'  {k}: {type(v).__name__}')
